MemoryConfig? loadAppMemoryConfig([String? projectDir]) {
  try {
    // Project-level .fah/config.yaml memory: wins (it travels in git).
    if (projectDir != null) {
      final project = loadProjectMemoryConfig(projectDir);
      if (project != null) return project;
